oxy_webhelp_navlinks = {"mt_sc_tenant_workloads_sc-d39307e67502":{"topics":[{"title":"Encryption on shared clusters","shortdesc":"<p class=\"shortdesc\">The MSP encrypts all tenant data on shared clusters at rest using a single         cluster-wide key. Tenants can independently configure encryption keys         for their own archival locations.<\/p>","href":"saas\/mt_sc_encryption_shared_clusters.html","attributes":{"data-id":"mt_sc_encryption_shared_clusters"},"menu":{"hasChildren":false},"tocID":"mt_sc_encryption_shared_clusters-d39307e67513","topics":[]},{"title":"SMB workloads on shared clusters","shortdesc":"<p class=\"shortdesc\">On shared clusters, all SMB workload operations require Active Directory         authentication. Tenants must register their Active Directory domain before performing any         SMB operation, and certain configurations can prevent SMB operations from completing         successfully.<\/p>","href":"saas\/mt_sc_smb_workloads_shared_clusters.html","attributes":{"data-id":"mt_sc_smb_workloads_shared_clusters"},"menu":{"hasChildren":false},"tocID":"mt_sc_smb_workloads_shared_clusters-d39307e67524","topics":[]},{"title":"Recovery target isolation on shared clusters","shortdesc":"<p class=\"shortdesc\">On shared clusters, Rubrik enforces tenant isolation for Live Mount recovery target         selection and Managed Volume exports. MSPs must also configure network controls at the         access layer to prevent cross-tenant access.<\/p>","href":"saas\/mt_sc_recovery_target_isolation.html","attributes":{"data-id":"mt_sc_recovery_target_isolation"},"menu":{"hasChildren":false},"tocID":"mt_sc_recovery_target_isolation-d39307e67535","topics":[]}]}};